import{_ as t,c as e,a2 as a,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"交易到底有没有秘密，或者说交易最核心的是什么？","description":"","frontmatter":{},"headers":[],"relativePath":"stock/游戏类比/游戏概率类比交易.md","filePath":"stock/游戏类比/游戏概率类比交易.md"}'),r={name:"stock/游戏类比/游戏概率类比交易.md"};function s(n,p,c,_,i,d){return o(),e("div",null,p[0]||(p[0]=[a('<h1 id="交易到底有没有秘密-或者说交易最核心的是什么" tabindex="-1">交易到底有没有秘密，或者说交易最核心的是什么？ <a class="header-anchor" href="#交易到底有没有秘密-或者说交易最核心的是什么" aria-label="Permalink to &quot;交易到底有没有秘密，或者说交易最核心的是什么？&quot;">​</a></h1><p>天启大烁哥</p><p>举个例子，你找到了一个抛硬币的游戏。</p><p>这个游戏的规则是，抛到正面你赢，抛到反面对方赢。你赢的时候，赢1块钱，你输的时候输2块。这个游戏你会参与吗？你不会参与。</p><p>胜率50%的情况下，盈亏比1:2。你玩久了肯定会输。</p><p>然后你又找到了一个抛硬币的游戏，这个游戏的规则是，如果你赢了，直接给你100块。但是你输了仅输1块钱。只不过，这个游戏你赢的条件是，你抛出的硬币必须立起来并且方向朝东北31.28度角。</p><p>这个游戏你会参与吗？你不会参与，因为虽然盈亏比足够高，但是胜率太低，玩久了还是输。</p><p>然后你又找到了一个游戏，这个游戏的规则是，抛到正面你赢，抛到反面对方赢。你赢的时候赢2块钱，你输的时候输1块。</p><p>这个规则对你而言是有利的，你可以在胜率50%的情况下，盈亏比2比1。这种情况下，你就可以通过资金管理去大量参与了，长期来看你是可以获利的。</p><p>对吧？</p><p>抛硬币的游戏，你该用什么样的规则去玩，问问自己，心里是不是很清晰了？</p><p>交易也是一样。</p><p>交易的核心，就是你建立起一套如第三种游戏的规则，这套规则整体让你有正期望，然后你以自己偏好的风险敞口去持续的输出这个概率优势。</p><p>说白了，就是带着概率优势持续的去“赌”。</p><p>这套规则的实现逻辑我也可以告诉你：</p><p><strong>入场试错，错了砍掉，盈利死拿，可以加仓，然后控制仓位，让自己在不顺利的时候别亏死了，直到顺利的时候来临，实现最终的概率优势</strong>。</p><p>这就是交易的核心。因为你做到了上述行为，你的交易行为理论上就具备了概率优势。</p><p>当然，以上是主观性描述，具体的落实细节上，那看个人认知理解以及风险偏好了。</p><p>有的人轻仓，有的人重仓，有的人集中梭哈单品种，有的人全面分散多品种，有的人加仓，有的人不加仓，有的人日线上建立规则，有的人分钟线上建规则。有的人基本面消息面试错，有的人量化系统化试错。</p><p>有问题吗？没有任何问题。</p><p>这些都是整个交易环节中微不足道的小细节而已。</p><p>关键就两点：持续输出，概率优势。组合到一起就是你能否活着并且长期持续输出概率优势。不确定的走势面前，处理走势的逻辑具备优势，这才是绝对的核心。</p><p>只要你的交易行为能够持续输出概率优势，你说你是夜观天象后下单也没有任何问题。</p>',23)]))}const f=t(r,[["render",s]]);export{m as __pageData,f as default};
